-- 📚 꼭집 주거 사전 — 보증금↔월임대료 전환 이율 · LH · 국민·영구·행복·매입 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 16.6초 · 결과:
-- {"anns": 73, "with_rate": 64, "up6": 52, "dn35": 43, "other": null, "cap60": 37, "m24": 28, "ex": ["20652_1_서울특별시_영등포구", "2015122300020840", "2015122300020816", "2015122300020814"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026),s as(select distinct announcement_id from y where cls='보증금 전환' and org='LH' and std in('국민임대','영구임대','행복주택','매입임대')),r as(select distinct y.announcement_id,x[1]::numeric v from y join s using(announcement_id) cross join lateral regexp_matches(y.t,'(?:연|이율|요율)\s*[:)]?\s*([0-9]+(?:\.[0-9]+)?)\s*%','g')x where y.cls='보증금 전환')select json_build_object('anns',(select count(*) from s),'with_rate',(select count(distinct announcement_id) from r),'up6',(select count(distinct announcement_id) from r where v=6),'dn35',(select count(distinct announcement_id) from r where v=3.5),'other',(select json_object_agg(v,n) from(select v,count(*)n from r where v not in(6,3.5) group by v)q),'cap60',(select count(distinct announcement_id) from y join s using(announcement_id) where cls='보증금 전환' and t~'최대\s*60\s*%'),'m24',(select count(distinct announcement_id) from y join s using(announcement_id) where cls='보증금 전환' and t~'24\s*개월'),'ex',(select json_agg(i) from(select announcement_id i from r where v=6 intersect select announcement_id from r where v=3.5 order by 1 desc limit 4)q))j;
